script:
frappe.listview_settings['ToDo'] = {
	onload: function(listview) {
		// Intercept row clicks on ToDo items that are linked to a Lead
		// and redirect to the Lead Activity Hub instead of the default ToDo form.
		listview.page.main.on('click', '.list-row', function(e) {
			var $row = $(this);

			// Do nothing if the click was on a checkbox or action button
			if ($(e.target).is('input[type=checkbox]') || $(e.target).closest('.list-row-checkbox').length) {
				return;
			}
			if ($(e.target).closest('.btn').length) {
				return;
			}

			var doc_name = $row.attr('data-name');
			if (!doc_name) return;

			// Check if this ToDo is linked to a Lead
			frappe.db.get_value('ToDo', doc_name, ['reference_type', 'reference_name'])
				.then(function(r) {
					if (r && r.message && r.message.reference_type === 'Lead' && r.message.reference_name) {
						// Intercept - go to Lead Activity Hub
						e.preventDefault();
						e.stopImmediatePropagation();
						frappe.set_route('lead-activity', r.message.reference_name);
					}
					// For non-Lead todos, default navigation proceeds
				});
		});
	}
};
